/// Load image from file into CPU memory (RAM)
pub fn loadImage(fileName: [:0]const u8) error{LoadFailed}!Image {
    const result = c.LoadImage(fileName.ptr);
    if (!c.IsImageValid(result)) return error.LoadFailed;
    return result;
}

/// Load image from RAW file data
pub fn loadImageRaw(fileName: [:0]const u8, width: i32, height: i32, format: PixelFormat, headerSize: i32) error{LoadFailed}!Image {
    const result = c.LoadImageRaw(fileName.ptr, width, height, @backingInt(format), headerSize);
    if (!c.IsImageValid(result)) return error.LoadFailed;
    return result;
}

pub const ImageAnim = struct { image: Image, frames: i32 };

/// Load image sequence from file (frames appended to image.data).
pub fn loadImageAnim(fileName: [:0]const u8) error{LoadFailed}!ImageAnim {
    var frames: c_int = 0;
    const image = c.LoadImageAnim(fileName.ptr, &frames);
    if (!c.IsImageValid(image)) return error.LoadFailed;
    return .{ .image = image, .frames = frames };
}

/// Load image sequence from memory buffer (fileType: ".gif").
pub fn loadImageAnimFromMemory(fileType: [:0]const u8, fileData: []const u8) error{LoadFailed}!ImageAnim {
    var frames: c_int = 0;
    const image = c.LoadImageAnimFromMemory(fileType.ptr, fileData.ptr, @intCast(fileData.len), &frames);
    if (!c.IsImageValid(image)) return error.LoadFailed;
    return .{ .image = image, .frames = frames };
}

/// Load image from memory buffer, fileType refers to extension: i.e. '.png'
pub fn loadImageFromMemory(fileType: [:0]const u8, fileData: []const u8) error{LoadFailed}!Image {
    const result = c.LoadImageFromMemory(fileType.ptr, fileData.ptr, @intCast(fileData.len));
    if (!c.IsImageValid(result)) return error.LoadFailed;
    return result;
}

/// Load image from GPU texture data
pub fn loadImageFromTexture(texture: Texture2D) error{LoadFailed}!Image {
    const result = c.LoadImageFromTexture(texture);
    if (!c.IsImageValid(result)) return error.LoadFailed;
    return result;
}

/// Load image from screen buffer (screenshot)
pub fn loadImageFromScreen() error{LoadFailed}!Image {
    const result = c.LoadImageFromScreen();
    if (!c.IsImageValid(result)) return error.LoadFailed;
    return result;
}

/// Check if an image is valid (data and parameters)
pub fn isImageValid(image: Image) bool {
    return c.IsImageValid(image);
}

/// Unload image from CPU memory (RAM)
pub fn unloadImage(image: Image) void {
    c.UnloadImage(image);
}

/// Export image data to file, returns true on success
pub fn exportImage(image: Image, fileName: [:0]const u8) bool {
    return c.ExportImage(image, fileName.ptr);
}

/// Export image to memory buffer (fileType: ".png"...). Free with `memFree`.
pub fn exportImageToMemory(image: Image, fileType: [:0]const u8) error{ExportFailed}![]u8 {
    var size: c_int = 0;
    const data = c.ExportImageToMemory(image, fileType.ptr, &size) orelse return error.ExportFailed;
    return data[0..@intCast(size)];
}

/// Export image as code file defining an array of bytes, returns true on success
pub fn exportImageAsCode(image: Image, fileName: [:0]const u8) bool {
    return c.ExportImageAsCode(image, fileName.ptr);
}

