        c.rlPushMatrix();
    }

    /// Pop latest inserted matrix from stack
    pub fn popMatrix() void {
        c.rlPopMatrix();
    }

    /// Reset current matrix to identity matrix
    pub fn loadIdentity() void {
        c.rlLoadIdentity();
    }

