    pub fn rotatef(angle: f32, x: f32, y: f32, z: f32) void {
        c.rlRotatef(angle, x, y, z);
    }

    /// Multiply the current matrix by a scaling matrix
    pub fn scalef(x: f32, y: f32, z: f32) void {
        c.rlScalef(x, y, z);
    }

