        c.rlEnableStereoRender();
    }

    /// Disable stereo rendering
    pub fn disableStereoRender() void {
        c.rlDisableStereoRender();
    }

    /// Check if stereo render is enabled
    pub fn isStereoRenderEnabled() bool {
        return c.rlIsStereoRenderEnabled();
    }

